<?php if(\App\Executives\TermService::ready()):$termCatalog=\App\Executives\TermService::catalog(); ?>
<section class="card mt-4"><div class="card-body"><h2 class="h6">Leadership administration</h2><p><?= e($appointment['leadership_term_name_snapshot']??'Not assigned to a leadership term') ?></p><?php if(\App\Auth::canManage()): ?><details><summary>Organize this appointment</summary><p class="small text-secondary mt-3">Grouping changes only the administration label. Original service identity and dates stay intact. The appointment must start within the selected administration's dates.</p><form method="post" action="<?= e(url('executive_appointment',['id'=>$appointment['id']])) ?>"><?= csrf() ?><input type="hidden" name="_action" value="executive_term_assign"><input type="hidden" name="appointment_id" value="<?= e($appointment['id']) ?>"><input type="hidden" name="version" value="<?= e($appointment['updated_at']) ?>"><?php $termOptions=[''=>'Not assigned'];foreach($termCatalog as $term){if($term['is_active']||(int)$term['id']===(int)($appointment['leadership_term_id']??0)){$termOptions[$term['id']]=$term['name'].' / '.$term['starts_on'].' – '.$term['ends_on'];}} ?><?= select_field('leadership_term_id','Leadership term',$termOptions,$appointment['leadership_term_id']??'') ?><button class="btn btn-sm btn-primary">Save grouping</button></form></details><?php endif; ?></div></section><?php endif; ?>
